function SolarProjectPortfolio({title="Solar Projects We've Delivered",description="A closer look at our solar installations across residential, commercial, and agricultural sites in Haryana."}:{title?:string;description?:string}){const [activeProjectIndex,setActiveProjectIndex]=useState<number|null>(null);const closeButtonRef=useRef<HTMLButtonElement>(null);const lightboxRef=useRef<HTMLDivElement>(null);const triggerRef=useRef<HTMLButtonElement|null>(null);const isOpen=activeProjectIndex!==null;useEffect(()=>{if(!isOpen)return;const previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';closeButtonRef.current?.focus();const handleKeyDown=(event:KeyboardEvent)=>{if(event.key==='Escape'){setActiveProjectIndex(null);return}if(event.key==='ArrowLeft'){setActiveProjectIndex(index=>index===null?null:(index+solarProjects.length-1)%solarProjects.length);return}if(event.key==='ArrowRight'){setActiveProjectIndex(index=>index===null?null:(index+1)%solarProjects.length);return}if(event.key==='Tab'&&lightboxRef.current){const buttons=Array.from(lightboxRef.current.querySelectorAll<HTMLButtonElement>('button:not([disabled])'));const first=buttons[0];const last=buttons[buttons.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}};document.addEventListener('keydown',handleKeyDown);return()=>{document.removeEventListener('keydown',handleKeyDown);document.body.style.overflow=previousOverflow;triggerRef.current?.focus()}},[isOpen]);const moveProject=(direction:number)=>setActiveProjectIndex(index=>index===null?null:(index+direction+solarProjects.length)%solarProjects.length);return <section className="section portfolio-section" aria-label="Our solar project portfolio"><div className="container"><SectionHeading eyebrow="OUR WORK" title={title} desc={description} center/><div className="portfolio-grid">{solarProjects.map((project,index)=><button className="portfolio-card" type="button" key={project.src} aria-label={`View project photo: ${project.title}`} onClick={event=>{triggerRef.current=event.currentTarget;setActiveProjectIndex(index)}}><span className="portfolio-image"><img src={project.src} alt={project.alt} loading="lazy" decoding="async"/></span><span className="portfolio-caption"><strong>{project.title}</strong><span>View photograph <ArrowUpRight size={14}/></span></span></button>)}</div></div>{activeProjectIndex!==null&&<div className="portfolio-lightbox" role="dialog" aria-modal="true" aria-labelledby="portfolio-lightbox-title" ref={lightboxRef} onClick={event=>{if(event.target===event.currentTarget)setActiveProjectIndex(null)}}><button className="portfolio-lightbox-close" type="button" aria-label="Close project photo" onClick={()=>setActiveProjectIndex(null)} ref={closeButtonRef}><X size={23}/></button><button className="portfolio-lightbox-nav portfolio-lightbox-prev" type="button" aria-label="Previous project photo" onClick={()=>moveProject(-1)}><ChevronLeft size={28}/></button><figure className="portfolio-lightbox-figure"><img src={solarProjects[activeProjectIndex].src} alt={solarProjects[activeProjectIndex].alt}/><figcaption id="portfolio-lightbox-title">{solarProjects[activeProjectIndex].title}<span>{activeProjectIndex+1} / {solarProjects.length}</span></figcaption></figure><button className="portfolio-lightbox-nav portfolio-lightbox-next" type="button" aria-label="Next project photo" onClick={()=>moveProject(1)}><ChevronRight size={28}/></button></div>}</section>}
