function ProductCard({item}:{item:typeof productData[number]}){const Icon=item.icon;return <article className="product-card"><Link to={item.href} className="product-image"><img src={item.image} alt={item.title+ ' solution'} loading="lazy"/><span className="product-tag">{item.tag}</span></Link><div className="product-body"><span className="product-icon"><Icon size={21}/></span><h3><Link to={item.href}>{item.title}</Link></h3><p>{item.desc}</p><Link to={item.href} className="card-link">Explore solution <ArrowRight size={16}/></Link></div></article>}
function WhyItem({title,desc}:{title:string;desc:string}){return <div className="why-item"><span><CheckCircle2 size={20}/></span><div><h3>{title}</h3><p>{desc}</p></div></div>}
const faqItems=[{q:'Who can qualify for PM Surya Ghar subsidy?',a:'The scheme is for eligible residential consumers and is subject to current official eligibility, application, equipment and installation requirements. Confirm your case on the official portal before relying on a subsidy estimate.'},{q:'Is ₹78,000 guaranteed for every customer?',a:'No. ₹78,000 is the standard central subsidy maximum for eligible residential systems of 3 kW or above under the commonly published structure. Eligibility and final disbursement depend on current rules and approved installation compliance.'},{q:'How much can I save with solar?',a:'Savings depend on your electricity consumption, tariff, system size, sunlight, roof shading, self-consumption and export-credit rules. A site-specific assessment and accurate bill data are needed for a useful estimate.'},{q:'Do solar panels have a 25-year warranty?',a:'Some manufacturers offer long performance warranties on eligible modules, but warranty terms vary by product and manufacturer. Ask for the exact product datasheet and written warranty terms.'},{q:'Will solar work during a power cut?',a:'A typical grid-tied system shuts down during a grid outage for safety. Backup during outages generally requires a suitable hybrid/off-grid design and compatible battery or backup configuration.'},{q:'Does Dangi Solar Solutions guarantee zero electricity bills?',a:'No. Electricity bills can include fixed charges and other components, and generation varies. We do not promise zero bills or guaranteed financial returns.'},{q:'Can commercial and agricultural customers receive the same subsidy?',a:'The standard PM Surya Ghar central residential subsidy should not automatically be applied to commercial or agricultural installations. Different programmes may have separate rules; verify the relevant official scheme.'},{q:'What affects installation cost?',a:'System capacity, equipment brand and model, roof or site conditions, mounting structure, wiring, safety equipment, approvals and the installation scope all affect cost. Request a written site-specific quotation.'}];
function FAQList({items}:{items:typeof faqItems}){const [opened,setOpened]=useState<number|null>(0);return <div className="faq-list">{items.map((f,i)=><div className={'faq-item '+(opened===i?'faq-open':'')} key={f.q}><button onClick={()=>setOpened(opened===i?null:i)} aria-expanded={opened===i}><span>{f.q}</span><ChevronDown size={19}/></button>{opened===i&&<p>{f.a}</p>}</div>)}</div>}
function CalculatorPanel({compact=false}:{compact?:boolean}){const [bill,setBill]=useState('3000');const [units,setUnits]=useState('350');const [category,setCategory]=useState('residential');const [discom,setDiscom]=useState('unknown');const [capacity,setCapacity]=useState('');const [cost,setCost]=useState('');const [show,setShow]=useState(false);const billN=Math.max(0,Number(bill)||0),unitsN=Math.max(0,Number(units)||0);const suggested=Math.min(10,Math.max(1,Math.ceil(unitsN/120)||1));const system=capacity?Math.max(0.5,Math.min(20,Number(capacity)||suggested)):suggested;const annualGeneration=system*1450;const selfUse=category==='residential'?0.78:0.7;const tariff=unitsN>0?billN/unitsN:7;const annualSavings=Math.min(billN*12,annualGeneration*selfUse*tariff);const subsidy=category==='residential'?Math.min(78000,Math.round(Math.min(system,2)*30000+Math.max(0,Math.min(system-2,1))*18000)):0;const estimatedCost=cost?Math.max(0,Number(cost)||0):system*60000;const netCost=Math.max(0,estimatedCost-subsidy);const payback=annualSavings>0?netCost/annualSavings:0;const money=(v:number)=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(v);return <div className={'calculator-panel '+(compact?'calculator-compact':'')}><div className="calculator-fields"><label>Monthly electricity bill (₹)<input type="number" min="0" value={bill} onChange={e=>setBill(e.target.value)} inputMode="numeric"/></label><label>Monthly consumption (units)<input type="number" min="0" value={units} onChange={e=>setUnits(e.target.value)} inputMode="numeric"/></label><label>Customer category<select value={category} onChange={e=>setCategory(e.target.value)}><option value="residential">Residential</option><option value="commercial">Commercial / Industrial</option><option value="agricultural">Agricultural</option></select></label>{!compact&&<><label>DISCOM<select value={discom} onChange={e=>setDiscom(e.target.value)}><option value="unknown">Not sure / confirm later</option><option value="dhbvn">DHBVN</option><option value="uhbvn">UHBVN</option></select></label><label>Known system capacity (kW)<input type="number" min="0.5" max="20" step="0.5" placeholder="Optional" value={capacity} onChange={e=>setCapacity(e.target.value)}/></label><label>Installation quote (₹)<input type="number" min="0" placeholder="Optional" value={cost} onChange={e=>setCost(e.target.value)}/></label></>}</div><button className="btn btn-primary calc-button" onClick={()=>setShow(true)}><Calculator size={17}/> Estimate my savings</button>{show&&<div className="calc-results" aria-live="polite"><div className="results-head"><span>YOUR INDICATIVE ESTIMATE</span><small>{discom==='unknown'?'DISCOM tariff not verified':discom.toUpperCase()+' selected'}</small></div><div className="results-grid"><Result label="Suggested system" value={`${system.toFixed(1)} kW`}/><Result label="Annual generation" value={`${Math.round(annualGeneration).toLocaleString('en-IN')} units`}/><Result label="Monthly average savings" value={money(annualSavings/12)}/><Result label="Annual savings" value={money(annualSavings)}/><Result label="Indicative subsidy" value={money(subsidy)}/><Result label="Estimated net investment" value={money(netCost)}/></div><div className="payback"><span>Simple payback estimate</span><strong>{payback>0&&Number.isFinite(payback)?`${payback.toFixed(1)} years`:'Not enough bill data'}</strong></div><p className="fineprint">Assumptions: 1,450 kWh per kW per year, estimated self-consumption of {Math.round(selfUse*100)}%, and an implied average bill/unit rate based on the figures entered. Indicative cost defaults to ₹60,000/kW. This is not verified tariff modelling; fixed charges, export credits, actual generation, taxes, approvals and actual quotes may change results. Subsidy is estimated only for residential category and is not guaranteed.</p></div>}</div>}
function Result({label,value}:{label:string;value:string}){return <div className="result-item"><span>{label}</span><strong>{value}</strong></div>}
function EnquirySection(){const [sent,setSent]=useState(false);const [name,setName]=useState('');const [phone,setPhone]=useState('');const [need,setNeed]=useState('Home Solar');const [details,setDetails]=useState('');const submit=(e:FormEvent)=>{e.preventDefault();const msg=`Solar enquiry for Dangi Solar Solutions%0AName: ${encodeURIComponent(name)}%0APhone: ${encodeURIComponent(phone)}%0ARequirement: ${encodeURIComponent(need)}%0ADetails: ${encodeURIComponent(details)}`;window.open(`https://wa.me/919466622220?text=${msg}`,'_blank','noopener,noreferrer');setSent(true)};return <section className="section enquiry-section" id="contact-form"><div className="container enquiry-grid"><div className="enquiry-copy"><span className="eyebrow eyebrow-light">LET'S TALK SOLAR</span><h2>Tell Us What You Need</h2><p>Tell us about your property, electricity requirements or solar project. Our team can help you explore suitable solutions and understand the next steps.</p><div className="contact-lines"><a href={`tel:${PHONE}`}><Phone/> <span><small>Call us</small><b>09466622220</b></span></a><a href={WA} target="_blank" rel="noreferrer"><MessageCircle/> <span><small>WhatsApp</small><b>Message our team</b></span></a><div><MapPin/><span><small>Visit</small><b>Amar Anaj Mandi, Israna, Panipat, Haryana 132107</b></span></div></div></div><form className="enquiry-form" onSubmit={submit}><h3>Request a consultation</h3><p>Share a few details and continue securely to WhatsApp to send your enquiry.</p><label>Your name<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Enter your name"/></label><label>Phone number<input required type="tel" pattern="[0-9+() -]{8,18}" value={phone} onChange={e=>setPhone(e.target.value)} placeholder="Your contact number"/></label><label>What do you need?<select value={need} onChange={e=>setNeed(e.target.value)}>{['Home Solar','Commercial Solar','Agricultural Solar','Inverters','Batteries','Streetlights','Water Pumps','Subsidy Guidance','Maintenance'].map(x=><option key={x}>{x}</option>)}</select></label><label>Project details (optional)<textarea value={details} onChange={e=>setDetails(e.target.value)} rows={3} placeholder="Property type, monthly bill, location…"/></label><button className="btn btn-primary form-submit" type="submit">Continue to WhatsApp <ArrowRight size={17}/></button>{sent&&<p className="form-note" role="status">WhatsApp should open in a new tab. If it did not, use the WhatsApp contact link above.</p>}<small className="form-privacy">Your details are used to respond to your enquiry. Do not include sensitive information.</small></form></div></section>}
function InnerPage({path}:{path:string}){const data=routeContent[path];if(!data)return <NotFound/>;if(path==='/about')return <AboutPage/>;if(path==='/solar-savings-calculator')return <><PageHero data={data}/><section className="section full-calculator"><div className="container calculator-layout"><div><SectionHeading eyebrow="SOLAR ESTIMATE" title="A useful starting point—not a promise" desc="Enter your current electricity bill and consumption. If you know your DISCOM, system capacity or quotation, add those details to improve the estimate."/><div className="assumption-card"><h3><CircleHelp size={18}/> What affects your result?</h3><p>Generation varies with system design, shade, weather and maintenance. Savings depend on tariff, self-consumption, export credits and fixed charges. We use simplified assumptions until verified local tariff data and a site-specific quotation are available.</p></div></div><CalculatorPanel/></div></section><EnquirySection/></>;
if(path==='/products-and-brands')return <><PageHero data={data}/><section className="section"><div className="container"><SectionHeading eyebrow="MANUFACTURER INFORMATION" title="Brands and products we can discuss" desc="Manufacturer identity and product categories should be confirmed against official sources and the products actually available through the business."/><div className="brand-grid brand-grid-page">{brands.map(b=><a className="brand-card" href={b.url} target="_blank" rel="noreferrer" key={b.name}><BrandIdentity brand={b}/><p>{b.desc}</p><span className="brand-link">View official website <ArrowUpRight size={14}/></span><span className="brand-quote">Ask about availability <ArrowRight size={15}/></span></a>)}</div></div></section><section className="section alt-section"><div className="container"><SectionHeading eyebrow="PRODUCT CATEGORIES" title="Match the product to the job" desc="Exact models, specifications and pricing are confirmed during the quotation process."/><div className="product-grid">{productData.map(p=><ProductCard key={p.href} item={p}/>)}</div></div></section><EnquirySection/></>;
if(path==='/pm-surya-ghar-subsidy')return <><PageHero data={data}/><section className="section"><div className="container subsidy-page-grid"><div><div className="subsidy-figure large"><span>Up to</span><strong>₹78,000</strong><small>standard central subsidy maximum for eligible residential rooftop systems</small></div><h2>Indicative central subsidy structure</h2><div className="subsidy-table"><div><b>1 kW</b><strong>₹30,000</strong></div><div><b>2 kW</b><strong>₹60,000</strong></div><div><b>3 kW or above</b><strong>Up to ₹78,000</strong></div></div><p className="fineprint">These are indicative figures from the commonly published standard central structure. Verify current scheme guidelines and any category-specific rules before launch or purchase.</p><CTA to="/contact">Check My Subsidy Eligibility</CTA></div><div className="scheme-page-image"><img src={images.home} alt="Residential rooftop solar panels" loading="lazy"/><div className="official-card"><ShieldCheck/><div><b>Check the official source</b><span>Eligibility, approvals and disbursement are controlled by the scheme rules—not by the installer.</span><a href={officialScheme} target="_blank" rel="noreferrer">Open PM Surya Ghar portal <ArrowUpRight size={14}/></a></div></div></div></div></section><section className="section alt-section"><div className="container"><SectionHeading eyebrow="HOW WE CAN HELP" title="Guidance through the process" desc="We can help you understand the steps; official eligibility and approval decisions remain with the relevant authorities."/><div className="three-grid"><SimpleCard n="01" title="Check eligibility" desc="Review the property, consumer connection and current official eligibility requirements."/><SimpleCard n="02" title="Prepare information" desc="Understand the application information and documents that may be required."/><SimpleCard n="03" title="Confirm compliance" desc="Check the approved process, equipment requirements, metering and submission steps."/></div></div></section><EnquirySection/></>;
if(path==='/projects')return <><PageHero data={data}/><SolarProjectPortfolio/><EnquirySection/></>;
if(path==='/reviews')return <><PageHero data={data}/><section className="section"><div className="container review-empty"><span className="review-icon"><CheckCircle2 size={28}/></span><SectionHeading eyebrow="VERIFIED FEEDBACK ONLY" title="No unverified testimonials" desc="The business has not supplied review texts and source links for this starter build. Add the three original reviews after confirming the wording, rating, customer attribution and source URL." center/><CTA to="/contact">Ask us a question</CTA></div></section><EnquirySection/></>;
if(path==='/faq')return <><PageHero data={data}/><section className="section"><div className="container faq-page-layout"><FAQList items={faqItems}/><aside className="faq-aside"><h3>Still have questions?</h3><p>Share your property type, bill and location for a more relevant discussion.</p><CTA to="/contact">Ask our team</CTA><a className="text-link" href={officialScheme} target="_blank" rel="noreferrer">Official PM Surya Ghar portal <ArrowUpRight size={15}/></a></aside></div></section><EnquirySection/></>;
if(path==='/contact')return <><PageHero data={data}/><section className="section contact-details-section"><div className="container contact-detail-grid"><SimpleCard n="01" title="Call" desc="Speak with the team about your solar requirements."/><SimpleCard n="02" title="Visit" desc="Amar Anaj Mandi, Israna, Panipat, Haryana 132107"/><SimpleCard n="03" title="WhatsApp" desc="Send your requirement and continue the conversation by WhatsApp."/></div></section><EnquirySection/></>;
if(path==='/privacy-policy'||path==='/terms')return <><PageHero data={data}/><section className="section"><div className="container legal-copy"><h2>{path==='/privacy-policy'?'Privacy and enquiry information':'Website terms and estimates'}</h2><p>{data.description}</p><p>This website is a business information and enquiry channel. Before public launch, the owner should review this page against the actual hosting, analytics, enquiry, CRM and data-retention setup. Nothing on this page is a substitute for legal advice.</p><h3>Contact</h3><p>For questions, contact DANGI SOLAR SOLUTIONS at 09466622220 or visit Amar Anaj Mandi, Israna, Panipat, Haryana 132107</p></div></section><EnquirySection/></>;
return <><PageHero data={data}/><section className="section"><div className="container detail-layout"><div className="detail-main"><SectionHeading eyebrow="THE RIGHT FIT STARTS WITH YOUR NEEDS" title={`Explore ${data.eyebrow.toLowerCase()}`} desc={data.description}/><div className="detail-image"><img src={data.image} alt={data.eyebrow+' — illustrative solar imagery'} loading="lazy"/><span className="placeholder-label">Illustrative category image</span></div><h2>What to consider</h2><div className="detail-benefits">{data.benefits.map((b,i)=><div key={b}><span>{String(i+1).padStart(2,'0')}</span><div><h3>{b}</h3><p>{benefitDetails[i%benefitDetails.length]}</p></div></div>)}</div><h2>Before you choose a system</h2><p>Product selection depends on your property, load profile, site conditions and budget. Exact models, prices, specifications, warranties and availability should be confirmed in a written quotation. Images on this starter website are illustrative unless clearly identified as verified project photographs.</p><div className="notice"><ShieldCheck/><p><b>Important:</b> Any subsidy, warranty, generation or savings figure must be checked against current official rules and manufacturer documentation. Results are not guaranteed.</p></div></div><aside className="detail-aside"><div className="aside-sticky"><span className="eyebrow">NEXT STEP</span><h3>Let's discuss your requirements</h3><p>Get guidance on product fit, installation considerations and the information needed for a quotation.</p><CTA to="/contact">Request a quote</CTA><a className="aside-phone" href={`tel:${PHONE}`}><Phone size={16}/> 09466622220</a><hr/><h4>Related pages</h4>{productData.filter(p=>p.href!==path).slice(0,5).map(p=><Link className="related-link" key={p.href} to={p.href}>{p.title}<ArrowUpRight size={14}/></Link>)}</div></aside></div></section><section className="section alt-section"><div className="container faq-layout"><div><SectionHeading eyebrow="COMMON QUESTIONS" title="Before you decide" desc="These general answers help frame the conversation. Product and scheme details vary."/></div><FAQList items={faqItems.slice(0,4)}/></div></section><EnquirySection/></>;
}
const benefitDetails=['We discuss your actual requirements before recommending a configuration.','We review relevant product documentation and compatibility rather than relying on brand names alone.','We explain key cost components, limitations and what is included in the proposed scope.','Final design, approvals, warranties and any scheme benefit depend on the specific project and current requirements.'];
function SimpleCard({n,title,desc}:{n:string;title:string;desc:string}){return <div className="simple-card"><span>{n}</span><h3>{title}</h3><p>{desc}</p></div>}
function PageHero({data}:{data:{title:string;eyebrow:string;description:string;image:string;benefits:string[]}}){return <section className="page-hero"><div className="container page-hero-grid"><div className="page-hero-copy"><span className="eyebrow">{data.eyebrow.toUpperCase()}</span><h1>{data.title}</h1><p>{data.description}</p><div className="page-hero-actions"><CTA to="/contact">Request a consultation</CTA><a className="btn btn-secondary" href={`tel:${PHONE}`}><Phone size={16}/> Call us</a></div></div><div className="page-hero-image"><img src={data.image} alt={data.eyebrow+' — illustrative image'} fetchPriority="high"/><span className="image-caption">Illustrative solar imagery</span></div></div></section>}
function NotFound(){return <section className="section not-found"><div className="container"><span className="eyebrow">404 · PAGE NOT FOUND</span><h1>That page isn't here.</h1><p>Use the main navigation to find the solar information you need.</p><CTA to="/">Return to home</CTA></div></section>}
function ScrollToTop(){const {pathname}=useLocation();useEffect(()=>{window.scrollTo({top:0,left:0,behavior:'instant'})},[pathname]);return null}
export default function App(){const loc=useLocation();return <><ScrollToTop/><Header/><main key={loc.pathname}><Routes><Route path="/" element={<Home/>}/>{Object.keys(routeContent).map(path=><Route key={path} path={path} element={<InnerPage path={path}/>}/>) }<Route path="*" element={<NotFound/>}/></Routes></main><Footer/><FloatingActions/></>}
